import{_ as a,o as e,c as o,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"先跑通一次，再存技能，最后才设例程","description":"","frontmatter":{"date":"2026-10-20T00:00:00.000Z","title":"先跑通一次，再存技能，最后才设例程","summary":"自动化最常见的翻车是「还没手动做顺就设了定时」。三步走的顺序，加上每一步可以直接复制的提示词。","category":"方法论","tags":["技能","例程","自动化"],"sources":[{"url":"https://docs.x.ai/grok-bot/faq","author":"Grok Bot FAQ","platform":"官方文档"},{"url":"https://docs.x.ai/grok-bot/skills-routines-and-automations","author":"Skills, routines, and automations","platform":"官方文档"}],"wordCount":352,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"先跑通一次，再存技能，最后才设例程 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"自动化最常见的翻车是「还没手动做顺就设了定时」。三步走的顺序，加上每一步可以直接复制的提示词。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-skill-before-routine"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-skill-before-routine-fdc1f41418.png"}],["meta",{"property":"og:image:alt","content":"先跑通一次，再存技能，最后才设例程 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"先跑通一次，再存技能，最后才设例程 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"自动化最常见的翻车是「还没手动做顺就设了定时」。三步走的顺序，加上每一步可以直接复制的提示词。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-skill-before-routine-fdc1f41418.png"}],["meta",{"name":"twitter:image:alt","content":"先跑通一次，再存技能，最后才设例程 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-skill-before-routine"}]]},"headers":[],"relativePath":"daily/2026-10-20-skill-before-routine.md","filePath":"daily/2026-10-20-skill-before-routine.md","lastUpdated":1792499451000}'),s={name:"daily/2026-10-20-skill-before-routine.md"};function i(l,t,r,p,c,d){return e(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="先跑通一次-再存技能-最后才设例程" tabindex="-1">先跑通一次，再存技能，最后才设例程 <a class="header-anchor" href="#先跑通一次-再存技能-最后才设例程" aria-label="Permalink to &quot;先跑通一次，再存技能，最后才设例程&quot;">​</a></h1><p>官方文档对技能和例程的区分只有一句话：<strong>技能说明&quot;怎么做&quot;，例程决定&quot;由哪个 Bot、什么时候做&quot;</strong>。并且建议：先在一次真实任务上测好技能，再把它变成例程。</p><p>道理很简单：一个没手动验证过的流程，设成定时以后只会<strong>每天准时地出错</strong>。</p><h2 id="第一步-当成一次性任务做一遍" tabindex="-1">第一步：当成一次性任务做一遍 <a class="header-anchor" href="#第一步-当成一次性任务做一遍" aria-label="Permalink to &quot;第一步：当成一次性任务做一遍&quot;">​</a></h2><p>不提&quot;每天&quot;，只说今天这一次，并要求它把过程讲出来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一次今天的竞品动态汇总：查 A、B、C 三家的官网更新页和官方 X 账号，</span></span>
<span class="line"><span>只要最近 24 小时的内容，每条一句话加原文链接。</span></span>
<span class="line"><span>做完后告诉我：你用了哪些来源、哪一步最费时间、哪里拿不准。</span></span></code></pre></div><p>看结果，挑毛病，让它改，直到你满意。<strong>这一步通常要两三轮。</strong></p><h2 id="第二步-把做顺的流程存成技能" tabindex="-1">第二步：把做顺的流程存成技能 <a class="header-anchor" href="#第二步-把做顺的流程存成技能" aria-label="Permalink to &quot;第二步：把做顺的流程存成技能&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把刚才这套做法保存成技能，名字叫&quot;竞品动态汇总&quot;。</span></span>
<span class="line"><span>写清楚：来源清单、时间范围、输出格式、遇到打不开的来源怎么处理、</span></span>
<span class="line"><span>哪些事情不要做（不发帖、不联系任何人）。</span></span></code></pre></div><p>存好后换一天再手动调用一次技能，确认它能独立复现。</p><h2 id="第三步-再设例程" tabindex="-1">第三步：再设例程 <a class="header-anchor" href="#第三步-再设例程" aria-label="Permalink to &quot;第三步：再设例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日 9:00，用&quot;竞品动态汇总&quot;技能跑一次，结果发在这个对话里。</span></span>
<span class="line"><span>如果某个来源打不开，在末尾列出来，不要用旧内容凑数。</span></span></code></pre></div><p>创建后先<strong>测试运行</strong>一次。注意：测试运行是真的在执行，不是演习。</p><h2 id="判断要不要自动化的三个问题" tabindex="-1">判断要不要自动化的三个问题 <a class="header-anchor" href="#判断要不要自动化的三个问题" aria-label="Permalink to &quot;判断要不要自动化的三个问题&quot;">​</a></h2><ol><li>这件事我是不是已经手动做过至少两三次、结果稳定？</li><li>出错时 Bot 会不会明说，而不是悄悄给我一份错的？</li><li>有没有&quot;不能撤回&quot;的动作（发送、发布、删除、购买）？有的话放在审批后面。</li></ol><p>三个都是&quot;是/有把握&quot;，再上例程。延伸阅读：<a href="/automation/skills">技能沉淀</a>、<a href="/automation/routines">例程：定时与事件触发</a>。</p>`,16)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
